def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "grab_foam_block": And([
            Not(self.foam_depth_safe),  # Foam depth is unsafe
            self.human_jumpers_present,  # Human jumpers are present
            self.foam_pit_has_safety_protocols  # Safety protocols are in place
        ]),  # Removing foam blocks when depth is unsafe with jumpers present is dangerous
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
